      [unfold estart; cbn [a_base a_off]; rewrite EA, u64_of_Z by lia; lia | apply elit_u; lia
      | unfold estart; cbn [a_base a_off]; rewrite (srl3_val _ (EVar 33) (wa_ff w) E33) by lia; lia | apply elit_u; lia
