  | |- sc_denot _ _ _ (SCDisj (SA (EAlu ALU_ADD (EVar 36) _) 0) (ELit ?l1) (SA (EVar 33) ?o2) (ELit ?l2)) =>
      eapply (sc_disj_lit asegs _ _ _ _ _ _ A l1 (wa_ff w + o2) l2);
